DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.crm_customer_save(jsonb)'::regprocedure) INTO d; d:=replace(d,'RETURN i; END','IF c.id IS NULL AND nullif(_data->>''next_local'','''') IS NOT NULL THEN PERFORM public.crm_schedule_save(jsonb_build_object(''customer_id'',i,''kind'',''appointment'',''due_at'',(_data->>''next_local'')||'':00+07:00'',''request_key'',k)); END IF; RETURN i; END'); EXECUTE d; SELECT pg_get_functiondef('public.crm_report(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid)'::regprocedure) INTO d; d:=replace(d,'WHERE c.created_at<hi AND crm_owner_visible(c.owner_id)','WHERE c.created_at<hi'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.crm_access_list() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT crm_can(auth.uid(),'biz.crm_access') THEN RAISE EXCEPTION 'Không có quyền xem cấp quyền CRM.'; END IF; RETURN (SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY started_at DESC),'[]') FROM crm_access_grants g); END $$;
REVOKE ALL ON FUNCTION public.crm_access_list() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_access_list() TO authenticated,service_role;